{# Mock Recall - Quality Report | Frappe v16 | Saved snapshot only. #}
{% set is_rtl = (frappe.lang or 'en')[:2] == 'ar' %}
{% set trace_rows = doc.get('trace_rows') or [] %}
{% set distribution_rows = doc.get('distribution_rows') or [] %}
{% set assessment = doc.get('result') or 'Not Evaluated' %}
{% set current_status = doc.get('status') or 'Draft' %}
{% set is_legacy = (doc.get('evidence_version') or 0) | int < 2 %}
{% set source_issues = (doc.get('snapshot_issues') or '') | trim %}
{% set exceptions = (doc.get('exceptions') or '') | trim %}
{% set trace_source_types = ['Stock Entry', 'Purchase Receipt', 'Purchase Invoice', 'Delivery Note', 'Sales Invoice', 'Pick List', 'Stock Reconciliation', 'POS Invoice'] %}
{% set evidence = namespace(unverified=0, discrepancy=0, candidates=0, unknown_scope=0, missing_quantities=0, invalid_evidence=false) %}
{% for row in trace_rows + distribution_rows %}
  {% if row.get('verification') == 'Discrepancy' %}{% set evidence.discrepancy = evidence.discrepancy + 1 %}
  {% elif row.get('verification') != 'Verified' %}{% set evidence.unverified = evidence.unverified + 1 %}{% endif %}
  {% if not (row.get('notes') or '') | trim %}{% set evidence.invalid_evidence = true %}{% endif %}
{% endfor %}
{% for row in trace_rows %}
  {% if not row.get('item_code') or row.get('reference_doctype') not in trace_source_types or not row.get('reference_name') or not row.get('uom') or row.get('qty') | float == 0 %}{% set evidence.invalid_evidence = true %}{% endif %}
{% endfor %}
{% for row in distribution_rows %}
  {% if row.get('evidence_type') == 'Item Candidate' %}{% set evidence.candidates = evidence.candidates + 1 %}
  {% elif row.get('evidence_type') != 'Batch' or not row.get('batch_no') %}{% set evidence.unknown_scope = evidence.unknown_scope + 1 %}{% endif %}
  {% if not row.get('item_code') or not row.get('voucher_type') or not row.get('voucher_no') or not row.get('uom') or row.get('qty') | float <= 0 %}{% set evidence.invalid_evidence = true %}{% endif %}
  {% if row.get('returned_qty') is none or row.get('net_qty') is none %}{% set evidence.missing_quantities = evidence.missing_quantities + 1 %}{% endif %}
{% endfor %}
{% set review_complete = doc.get('quantity_verified') and doc.get('customers_verified') and doc.get('genealogy_verified') %}
{% set coverage_complete = (doc.get('coverage_notes') or '') | trim %}
{% set trace_count_matches = doc.get('trace_row_count') == (trace_rows | length) %}
{# Structured snapshot issues and saved review/evidence checks still
   determine approval support; deleted print sections are intentionally omitted. #}
{% set approval_blocked = is_legacy or not trace_rows or not trace_count_matches or current_status != 'Closed' or not doc.get('reviewed_by') or not doc.get('reviewed_at') or not review_complete or not coverage_complete or source_issues or exceptions or evidence.unverified or evidence.discrepancy or evidence.candidates or evidence.unknown_scope or evidence.invalid_evidence or evidence.missing_quantities %}
{% set contradiction = assessment == 'Passed' and approval_blocked %}

{# Preserve ordinary rich-text paragraph/list breaks, then strip tags and escape.
   A visible text marker survives striptags whitespace normalization. User HTML
   is never marked safe; plain text fields are escaped without stripping. #}
{% macro plain_text(value) -%}
  {% set marker = 'MOCK_RECALL_LINE_BREAK_7E6B' %}
  {% set text = (value or '-') | string
    | replace('<br>', marker) | replace('<br/>', marker) | replace('<br />', marker)
    | replace('<BR>', marker) | replace('<BR/>', marker) | replace('<BR />', marker)
    | replace('</p>', marker) | replace('</P>', marker) | replace('</div>', marker)
    | replace('</li>', marker) | replace('</blockquote>', marker) | replace('</tr>', marker)
    | replace('</h1>', marker) | replace('</h2>', marker) | replace('</h3>', marker) %}
  {{- text | striptags | replace(marker | trim, '\n') | trim | e -}}
{%- endmacro %}
{% macro verification(value) -%}
  <span class="status {{ 'verified' if value == 'Verified' else 'discrepancy' if value == 'Discrepancy' else 'pending' }}">
    {%- if value == 'Verified' -%}{{ _('Verified', context='Mock Recall Quality Report') }}
    {%- elif value == 'Discrepancy' -%}{{ _('Discrepancy', context='Mock Recall Quality Report') }}
    {%- else -%}{{ _('Unverified', context='Mock Recall Quality Report') }}{%- endif -%}
  </span>
{%- endmacro %}
{% macro assessment_badge() -%}
  <span class="status {{ 'discrepancy' if contradiction else 'passed' if assessment == 'Passed' else 'failed' if assessment == 'Failed' else 'pending' }}">
    {%- if contradiction -%}{{ _('Evidence Incomplete', context='Mock Recall Quality Report') }}
    {%- elif assessment == 'Passed' -%}{{ _('Passed', context='Mock Recall Quality Report') }}
    {%- elif assessment == 'Failed' -%}{{ _('Failed', context='Mock Recall Quality Report') }}
    {%- else -%}{{ _('Not Evaluated', context='Mock Recall Quality Report') }}{%- endif -%}
  </span>
{%- endmacro %}
{% macro formatted_date(record, fieldname) -%}
  {% if record.get(fieldname) %}<span class="latin">{{ record.get_formatted(fieldname) | e }}</span>{% else %}-{% endif %}
{%- endmacro %}

<div class="mock-print" dir="{{ 'rtl' if is_rtl else 'ltr' }}" lang="{{ 'ar' if is_rtl else 'en' }}">
  <table class="paper-heading"><tr>
    <td class="pf-heading-main">
      <h1 class="title">{{ _('Mock Recall - Quality Report', context='Mock Recall Quality Report') }}</h1>
      <div class="exercise-title" dir="auto">{{ (doc.get('title') or '-') | e }}</div>
    </td>
    <td class="pf-heading-ref"><div class="refblock">
      <div class="ref-small">{{ _('Mock Recall Reference', context='Mock Recall Quality Report') }}</div>
      <div class="ref-code">{{ doc.name | e }}</div>
      <div class="ref-small pf-ref-topgap">{{ (doc.get('company') or '-') | e }}</div>
    </div></td>
  </tr></table>

  <table class="info">
    <tr><td><div class="lab">{{ _('Company', context='Mock Recall Quality Report') }}</div><div class="val">{{ (doc.get('company') or '-') | e }}</div></td>
      <td><div class="lab">{{ _('Record ID', context='Mock Recall Quality Report') }}</div><div class="val code">{{ doc.name | e }}</div></td></tr>
    <tr><td><div class="lab">{{ _('Scenario Type', context='Mock Recall Quality Report') }}</div><div class="val">
      {% if doc.get('scenario_type') == 'Finished Product' %}{{ _('Finished Product', context='Mock Recall Quality Report') }}
      {% elif doc.get('scenario_type') == 'Raw Material' %}{{ _('Raw Material', context='Mock Recall Quality Report') }}
      {% elif doc.get('scenario_type') == 'Preparation' %}{{ _('Preparation', context='Mock Recall Quality Report') }}
      {% elif doc.get('scenario_type') == 'Packaging Material' %}{{ _('Packaging Material (Legacy)', context='Mock Recall Quality Report') }}
      {% else %}{{ (doc.get('scenario_type') or '-') | e }}{% endif %}
    </div></td><td><div class="lab">{{ _('Trace Snapshot', context='Mock Recall Quality Report') }}</div><div class="val">{{ formatted_date(doc, 'snapshot_date') }}</div></td></tr>
    <tr><td><div class="lab">{{ _('Item Under Review', context='Mock Recall Quality Report') }}</div><div class="val code">{{ (doc.get('item_code') or '-') | e }}</div></td>
      <td><div class="lab">{{ _('Batch No.', context='Mock Recall Quality Report') }}</div><div class="val code">{{ (doc.get('batch_no') or '-') | e }}</div></td></tr>
    <tr><td><div class="lab">{{ _('Started At', context='Mock Recall Quality Report') }}</div><div class="val">{{ formatted_date(doc, 'started_at') }}</div></td>
      <td><div class="lab">{{ _('Tracing Completed At', context='Mock Recall Quality Report') }}</div><div class="val">{{ formatted_date(doc, 'completed_at') }}</div></td></tr>
    <tr><td><div class="lab">{{ _('Document Status', context='Mock Recall Quality Report') }}</div><div class="val"><span class="status neutral">
      {% if current_status == 'Draft' %}{{ _('Draft', context='Mock Recall Quality Report') }}
      {% elif current_status == 'Traced' %}{{ _('Traced', context='Mock Recall Quality Report') }}
      {% elif current_status == 'Under Review' %}{{ _('Under Review', context='Mock Recall Quality Report') }}
      {% elif current_status == 'Closed' %}{{ _('Closed', context='Mock Recall Quality Report') }}
      {% else %}{{ current_status | e }}{% endif %}
    </span></div></td><td><div class="lab">{{ _('Assessment Result', context='Mock Recall Quality Report') }}</div><div class="val">{{ assessment_badge() }}</div></td></tr>
  </table>

  <section class="section"><h2 class="section-title">{{ _('Executive Snapshot', context='Mock Recall Quality Report') }}</h2>
    <table class="metrics"><tr>
      <td><div class="metric-val">{{ trace_rows | length }}</div><div class="metric-lab">{{ _('Trace Records', context='Mock Recall Quality Report') }}</div></td>
      <td><div class="metric-val">{{ distribution_rows | length }}</div><div class="metric-lab">{{ _('Distribution Rows', context='Mock Recall Quality Report') }}</div></td>
      <td><div class="metric-val">{{ (doc.get('customer_count') if doc.get('customer_count') is not none else '-') | e }}</div><div class="metric-lab">{{ _('Customers Found (snapshot)', context='Mock Recall Quality Report') }}</div></td>
      <td><div class="metric-val">{{ (doc.get('elapsed_seconds') if doc.get('elapsed_seconds') is not none else '-') | e }}</div><div class="metric-lab">{{ _('Tracing Duration (seconds)', context='Mock Recall Quality Report') }}</div></td>
    </tr></table>
    <div class="verification-summary">
      <span>{{ _('Unverified', context='Mock Recall Quality Report') }}: <b>{{ evidence.unverified }}</b></span>
      <span>{{ _('Discrepancy', context='Mock Recall Quality Report') }}: <b>{{ evidence.discrepancy }}</b></span>
      <span>{{ _('Item/date Candidates', context='Mock Recall Quality Report') }}: <b>{{ evidence.candidates }}</b></span>
    </div>
  </section>

  <section class="section"><h2 class="section-title">{{ _('Exercise Scope and Details', context='Mock Recall Quality Report') }}</h2>
    <div class="descbox"><div class="lab">{{ _('Reason for Exercise', context='Mock Recall Quality Report') }}</div><div class="body" dir="auto">{{ (doc.get('reason') or '-') | e }}</div></div>
    <div class="descbox"><div class="lab">{{ _('Exercise Objective', context='Mock Recall Quality Report') }}</div><div class="body" dir="auto">{{ (doc.get('objective') or '-') | e }}</div></div>
    {% if doc.get('coverage_notes') %}<div class="descbox"><div class="lab">{{ _('Quantity Reconciliation and Coverage Notes', context='Mock Recall Quality Report') }}</div><div class="body" dir="auto">{{ doc.get('coverage_notes') | e }}</div></div>{% endif %}
  </section>



  <section class="section" id="trace-evidence"><h2 class="section-title">{{ _('Traceability Evidence', context='Mock Recall Quality Report') }}</h2>
    <table class="data-table trace-table"><thead><tr>
      <th class="col-number">{{ _('No.', context='Mock Recall Quality Report') }}</th>
      <th class="trace-col-direction">{{ _('Direction / Level', context='Mock Recall Quality Report') }}</th>
      <th class="trace-col-item">{{ _('Item / Batch', context='Mock Recall Quality Report') }}</th>
      <th class="trace-col-qty">{{ _('Quantity / UOM', context='Mock Recall Quality Report') }}</th>
      <th class="trace-col-source">{{ _('Source and Parties', context='Mock Recall Quality Report') }}</th>
      <th class="trace-col-review">{{ _('Verification', context='Mock Recall Quality Report') }}</th>
    </tr></thead><tbody>
    {% for r in trace_rows %}<tr>
      <td class="center">{{ loop.index }}</td>
      <td>{% if r.get('direction') == 'Backward' %}{{ _('Backward Trace', context='Mock Recall Quality Report') }}{% elif r.get('direction') == 'Forward' %}{{ _('Forward Trace', context='Mock Recall Quality Report') }}{% else %}{{ (r.get('direction') or '-') | e }}{% endif %}
        <div class="minor">{{ _('Trace Level', context='Mock Recall Quality Report') }}: {{ (r.get('trace_level') if r.get('trace_level') is not none else '-') | e }}</div></td>
      <td><div class="code">{{ (r.get('item_code') or '-') | e }}</div><div class="minor code">{{ (r.get('batch_no') or '-') | e }}</div>
        {% if r.get('warehouse') %}<div class="minor">{{ _('Warehouse', context='Mock Recall Quality Report') }}: <span dir="auto">{{ r.get('warehouse') | e }}</span></div>{% endif %}</td>
      <td><div class="qty">{{ (r.get('qty') if r.get('qty') is not none else '-') | e }}</div><div class="minor" dir="auto">{{ (r.get('uom') or '-') | e }}</div></td>
      <td><div class="small" dir="auto">{{ (r.get('reference_doctype') or '-') | e }}</div><div class="code">{{ (r.get('reference_name') or '-') | e }}</div>
        <div class="minor">{{ _('Posting Date and Time', context='Mock Recall Quality Report') }}: {{ formatted_date(r, 'posting_datetime') }}</div>
        {% if r.get('work_order') %}<div class="minor">{{ _('Work Order', context='Mock Recall Quality Report') }}: <span class="code">{{ r.get('work_order') | e }}</span></div>{% endif %}
        {% if r.get('supplier') %}<div class="minor">{{ _('Supplier', context='Mock Recall Quality Report') }}: <span dir="auto">{{ r.get('supplier') | e }}</span></div>{% endif %}
        {% if r.get('customer') %}<div class="minor">{{ _('Customer', context='Mock Recall Quality Report') }}: <span dir="auto">{{ r.get('customer') | e }}</span></div>{% endif %}</td>
      <td>{{ verification(r.get('verification')) }}{% if r.get('notes') %}<div class="row-note" dir="auto">{{ r.get('notes') | e }}</div>{% endif %}</td>
    </tr>{% else %}<tr><td colspan="6" class="pf-no-records">{{ _('No Records Available', context='Mock Recall Quality Report') }}</td></tr>{% endfor %}
    </tbody></table>
  </section>

  <section class="section evidence-section" id="distribution-evidence"><h2 class="section-title">{{ _('Distribution and Customer Evidence', context='Mock Recall Quality Report') }}</h2>
    <table class="data-table distribution-table"><thead><tr>
      <th class="col-number">{{ _('No.', context='Mock Recall Quality Report') }}</th>
      <th class="distribution-col-source">{{ _('Customer / Reference', context='Mock Recall Quality Report') }}</th>
      <th class="distribution-col-item">{{ _('Item / Batch / Scope', context='Mock Recall Quality Report') }}</th>
      <th class="col-quantity">{{ _('Gross Qty', context='Mock Recall Quality Report') }}</th>
      <th class="col-quantity">{{ _('Returned Qty', context='Mock Recall Quality Report') }}</th>
      <th class="col-quantity">{{ _('Net Qty', context='Mock Recall Quality Report') }}</th>
      <th class="distribution-col-review">{{ _('Verification', context='Mock Recall Quality Report') }}</th>
    </tr></thead><tbody>
    {% for r in distribution_rows %}
      <tr class="evidence-row">
        <td class="center">{{ loop.index }}</td>
        <td><div dir="auto">{{ (r.get('customer') or '-') | e }}</div><div class="small" dir="auto">{{ (r.get('voucher_type') or '-') | e }}</div><div class="code">{{ (r.get('voucher_no') or '-') | e }}</div></td>
        <td><div class="code">{{ (r.get('item_code') or '-') | e }}</div><div class="minor code">{{ r.get('batch_no') | e if r.get('batch_no') else _('No Batch', context='Mock Recall Quality Report') }}</div>
          {% if is_legacy %}<div class="minor">{{ _('Legacy', context='Mock Recall Quality Report') }}</div>
          {% elif r.get('evidence_type') == 'Item Candidate' %}<div class="minor">{{ _('Item Candidate', context='Mock Recall Quality Report') }}</div>
          {% elif r.get('evidence_type') == 'Batch' and r.get('batch_no') %}<div class="minor">{{ _('Batch', context='Mock Recall Quality Report') }}</div>
          {% else %}<div class="minor">{{ _('Unclassified', context='Mock Recall Quality Report') }}</div>{% endif %}
          <div class="minor">{{ _('UOM', context='Mock Recall Quality Report') }}: <span dir="auto">{{ (r.get('uom') or '-') | e }}</span></div></td>
        <td><span class="qty" data-quantity="gross">{{ (r.get('qty') if r.get('qty') is not none else '-') | e }}</span></td>
        <td><span class="qty" data-quantity="returned">{{ (r.get('returned_qty') if not is_legacy and r.get('returned_qty') is not none else '-') | e }}</span></td>
        <td><span class="qty" data-quantity="net">{{ (r.get('net_qty') if not is_legacy and r.get('net_qty') is not none else '-') | e }}</span></td>
        <td>{{ verification(r.get('verification')) }}
          {% if r.get('notes') %}<div class="row-note" dir="auto"><b>{{ _('QC Notes', context='Mock Recall Quality Report') }}</b><div>{{ r.get('notes') | e }}</div></div>{% endif %}</td>
      </tr>
    {% else %}<tr><td colspan="7" class="pf-no-records">{{ _('No Records Available', context='Mock Recall Quality Report') }}</td></tr>{% endfor %}
    </tbody></table>
  </section>

  <section class="section"><h2 class="section-title">{{ _('Evidence Verification Checklist', context='Mock Recall Quality Report') }}</h2>
    <table class="checks"><tr>
      <td><div class="lab">{{ _('Quantity Reconciliation', context='Mock Recall Quality Report') }}</div><span class="status {{ 'verified' if doc.get('quantity_verified') else 'pending' }}">{{ _('Verified', context='Mock Recall Quality Report') if doc.get('quantity_verified') else _('Not Verified', context='Mock Recall Quality Report') }}</span></td>
      <td><div class="lab">{{ _('Customer Verification', context='Mock Recall Quality Report') }}</div><span class="status {{ 'verified' if doc.get('customers_verified') else 'pending' }}">{{ _('Verified', context='Mock Recall Quality Report') if doc.get('customers_verified') else _('Not Verified', context='Mock Recall Quality Report') }}</span></td>
      <td><div class="lab">{{ _('Manufacturing Genealogy', context='Mock Recall Quality Report') }}</div><span class="status {{ 'verified' if doc.get('genealogy_verified') else 'pending' }}">{{ _('Verified', context='Mock Recall Quality Report') if doc.get('genealogy_verified') else _('Not Verified', context='Mock Recall Quality Report') }}</span></td>
    </tr></table>
  </section>

  {% set has_review_notes = doc.get('exceptions') or doc.get('review_notes') or doc.get('closure_notes') %}
  {% if has_review_notes %}
  <section class="section"><h2 class="section-title">{{ _('Exceptions and Review Notes', context='Mock Recall Quality Report') }}</h2>
    {% if doc.get('exceptions') %}<div class="descbox"><div class="lab">{{ _('Exceptions', context='Mock Recall Quality Report') }}</div><div class="body" dir="auto">{{ plain_text(doc.get('exceptions')) }}</div></div>{% endif %}
    {% if doc.get('review_notes') %}<div class="descbox"><div class="lab">{{ _('Quality Review Notes', context='Mock Recall Quality Report') }}</div><div class="body" dir="auto">{{ plain_text(doc.get('review_notes')) }}</div></div>{% endif %}
    {% if doc.get('closure_notes') %}<div class="descbox"><div class="lab">{{ _('Closure Notes', context='Mock Recall Quality Report') }}</div><div class="body" dir="auto">{{ plain_text(doc.get('closure_notes')) }}</div></div>{% endif %}
  </section>{% endif %}

  <section class="section" id="assessment"><h2 class="section-title">{{ _('Assessment and Closure', context='Mock Recall Quality Report') }}</h2>
    <div class="result-card"><table class="result-table">
      <tr><td class="pf-assessment-label">{{ _('Assessment Result', context='Mock Recall Quality Report') }}</td><td>{{ assessment_badge() }}</td></tr>
      <tr><td class="pf-assessment-label-text">{{ _('Reviewed By', context='Mock Recall Quality Report') }}</td><td class="code">{{ (doc.get('reviewed_by') or '-') | e }}</td></tr>
      <tr><td class="pf-assessment-label-text">{{ _('Reviewed At', context='Mock Recall Quality Report') }}</td><td>{{ formatted_date(doc, 'reviewed_at') }}</td></tr>
      {% if doc.get('quality_action') %}<tr><td class="pf-assessment-label-text">{{ _('Related Quality Action', context='Mock Recall Quality Report') }}</td><td class="code">{{ doc.get('quality_action') | e }}</td></tr>{% endif %}
      {% if doc.get('quality_review') %}<tr><td class="pf-assessment-label-text">{{ _('Related Quality Review', context='Mock Recall Quality Report') }}</td><td class="code">{{ doc.get('quality_review') | e }}</td></tr>{% endif %}
    </table></div>
    <div class="signature-block">
      <table class="signature"><tr><td><div class="lab">{{ _('Quality Officer Name and Signature', context='Mock Recall Quality Report') }}</div><div class="signline"></div><div class="minor">{{ _('Date', context='Mock Recall Quality Report') }}: __________</div></td>
        <td><div class="lab">{{ _('Quality Manager Name and Signature', context='Mock Recall Quality Report') }}</div><div class="signline"></div><div class="minor">{{ _('Date', context='Mock Recall Quality Report') }}: __________</div></td></tr></table>
    </div>
  </section>
</div>

css:
@page {size:A4 portrait; margin:13mm 12mm 15mm;}
.mock-print {font:10px/1.55 Arial,"Noto Sans Arabic",Tahoma,sans-serif; color:#2c3338;}
.mock-print[dir="rtl"] {direction:rtl; font-family:"Noto Sans Arabic",Tahoma,Arial,sans-serif;}
.mock-print[dir="ltr"] {direction:ltr;}
.mock-print * {box-sizing:border-box;}
.mock-print h1,.mock-print h2 {font-family:inherit;}
.mock-print .paper-heading {width:100%;border-collapse:collapse;margin:4px 0 12px;}
.mock-print .paper-heading td {border:0;padding:0;vertical-align:top;}
.mock-print .pf-heading-main {width:72%;}
.mock-print .pf-heading-ref {width:28%;text-align:end;}
.mock-print .title {font-size:19px;font-weight:700;color:#2c3338;margin:0 0 4px;}
.mock-print .exercise-title {font-size:11px;font-weight:600;white-space:pre-wrap;overflow-wrap:anywhere;}
.mock-print .refblock {direction:ltr;text-align:end;}
.mock-print .ref-small,.mock-print .lab,.mock-print .metric-lab {font-size:9px;color:#68747e;}
.mock-print .ref-code {font:700 12px Arial,sans-serif;overflow-wrap:anywhere;}
.mock-print .pf-ref-topgap {margin-top:5px;}
.mock-print .info {width:100%;border-collapse:collapse;table-layout:fixed;}
.mock-print .info td {padding:6px 8px;border-bottom:1px solid #d1d8dd;vertical-align:top;width:50%;}
.mock-print .val {font-weight:600;font-size:10px;overflow-wrap:anywhere;white-space:pre-wrap;}
.mock-print .section {margin-top:14px;}
.mock-print .section-title {font-size:12px;font-weight:700;margin:0 0 6px;padding-bottom:4px;border-bottom:1px solid #c8d0d6;break-after:avoid;page-break-after:avoid;}
.mock-print .metrics {width:100%;border-collapse:collapse;table-layout:fixed;margin:7px 0;}
.mock-print .metrics td {width:25%;padding:6px;text-align:center;border:1px solid #d1d8dd;}
.mock-print .metric-val {font:700 17px Arial,sans-serif;direction:ltr;}
.mock-print .verification-summary {margin:6px 0;color:#555;}
.mock-print .verification-summary span {display:inline-block;margin-inline-end:16px;}
.mock-print .descbox {border-bottom:1px solid #e0e3e6;margin-bottom:7px;padding:4px 0;break-inside:auto;page-break-inside:auto;}
.mock-print .descbox .body {white-space:pre-wrap;overflow-wrap:anywhere;}
.mock-print .checks {width:100%;border-collapse:collapse;table-layout:fixed;}
.mock-print .checks td {border:1px solid #d1d8dd;padding:7px;width:33.333%;text-align:center;}
.mock-print .data-table {width:100%;border-collapse:collapse;table-layout:fixed;font-size:9px;margin-top:7px;}
.mock-print .data-table thead {display:table-header-group;}
.mock-print .data-table th {text-align:start;background:#f4f5f6;border-bottom:1px solid #bfc6cd;padding:6px 5px;vertical-align:middle;}
.mock-print .data-table td {padding:5px;border-bottom:1px solid #e1e5e8;vertical-align:top;overflow-wrap:anywhere;}
.mock-print .data-table tr {break-inside:avoid;page-break-inside:avoid;}
.mock-print .data-table .minor,.mock-print .data-table .small,.mock-print .row-note {font-size:8px;color:#68747e;}
.mock-print .data-table .center {text-align:center;}
.mock-print .status {font-size:9px;font-weight:600;color:#36434d;}
.mock-print .latin,.mock-print .code,.mock-print .qty {unicode-bidi:isolate;overflow-wrap:anywhere;}
.mock-print .code {font-family:Arial,sans-serif;font-weight:600;direction:ltr;}
.mock-print .qty {font:10px Arial,sans-serif;direction:ltr;}
.mock-print .row-note {margin-top:4px;white-space:pre-wrap;}
.mock-print .pf-assessment-label,.mock-print .pf-assessment-label-text {color:#68747e;width:32%;}
.mock-print .result-card {border:1px solid #d1d8dd;padding:8px;break-inside:avoid;page-break-inside:avoid;}
.mock-print .result-table {width:100%;border-collapse:collapse;}
.mock-print .result-table td {padding:5px;border-bottom:1px solid #e1e5e8;}
.mock-print .result-table tr:last-child td {border-bottom:0;}
.mock-print .signature-block {break-inside:avoid;page-break-inside:avoid;}
.mock-print .signature {width:100%;table-layout:fixed;border-spacing:5px;margin:12px 0;}
.mock-print .signature td {width:50%;height:66px;border:1px solid #d1d8dd;padding:7px;vertical-align:top;}
.mock-print .signline {border-bottom:1px solid #98a3ad;margin-top:24px;width:96%;}
.mock-print .pf-no-records {text-align:center;color:#68747e;padding:10px;}
.mock-print .col-number {width:4%;}
.mock-print .trace-col-direction {width:12%;}
.mock-print .trace-col-item {width:21%;}
.mock-print .trace-col-qty {width:10%;}
.mock-print .trace-col-source {width:30%;}
.mock-print .trace-col-review {width:23%;}
.mock-print .distribution-col-source {width:21%;}
.mock-print .distribution-col-item {width:23%;}
.mock-print .col-quantity {width:9%;}
.mock-print .distribution-col-review {width:25%;}
@media screen {.mock-print {max-width:190mm;margin:0 auto;background:white;padding:4px;}}
@media print {.mock-print {max-width:none;padding:0;}}
